const mix=(a,b,t)=>a.map((v,i)=>Math.round(v+(b[i]-v)*t));
function uniform(fin){intro(1,'UNIFORM CHECK','Cadet, a parade begins with a spotless uniform. I will inspect you from cap to boots. Tap each fault on the cadet and put it right.','START INSPECTION',()=>{
 try{LS.setItem(SK,'{}')}catch(e){}
 const need={beret:1,btn:1,buckle:3,shoes:3},got={beret:0,btn:0,buckle:0,shoes:0},L={beret:'Beret straight',btn:'Collar button closed',buckle:'Belt buckle shining',shoes:'Boots polished'};let miss=0,fid=0,fixed=0,att=false;
 M.innerHTML='<div class="q" id="pq">Eyes front, cadet. Find what is wrong with this uniform.</div><div class="uni"><div class="figw">'+FIG+'</div><div class="uside">'+Object.keys(L).map(k=>'<div class="ck" data-c="'+k+'"><b>!</b>'+L[k]+'</div>').join('')+'<div id="pa"></div></div></div>';
 const q=t=>{$('#pq').textContent=t},msg={beret:'Beret straight. Good.',btn:'Collar closed. Neat.',buckle:'That buckle gleams like a mirror.',shoes:'Boots like black glass. Fine.',more:{buckle:'Rub it again, cadet. More shine!',shoes:'Again! I want to see my face in those boots.'}};
 const fix=k=>{if(got[k]>=need[k])return;got[k]++;beep(500+got[k]*120,.08,'triangle');vib(15);const t=got[k]/need[k];
  if(k==='beret')$('#u-be').style.transform='rotate(0deg)';
  if(k==='btn'){$('#u-open').style.display='none';$('#u-b1').setAttribute('fill','#fff')}
  if(k==='buckle'){$('#u-bk').setAttribute('fill','rgb('+mix([139,122,74],[255,213,74],t).join(',')+')');$('#u-sp').setAttribute('opacity',t>=1?1:0)}
  if(k==='shoes'){$('#u-sh').children[0].setAttribute('fill','rgb('+mix([107,90,70],[14,14,18],t).join(',')+')');$('#u-sh').children[1].setAttribute('fill','rgb('+mix([107,90,70],[14,14,18],t).join(',')+')');$('#u-dust').style.opacity=1-t;$('#u-sh').children[1].setAttribute('opacity',1-t)}
  if(got[k]>=need[k]){fixed++;q(msg[k]);ov.querySelector('.mk[data-k='+k+']').style.display='none';const c=ov.querySelector('.ck[data-c='+k+']');c.classList.add('ok');c.firstChild.textContent='\u2713';ok_();if(fixed===4)sleep(700,phase2)}else q(msg.more[k]||'')};
 ov.querySelectorAll('.hz').forEach(h=>h.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();if(!att)fix(h.dataset.k)}));
 ov.querySelector('.uni svg').addEventListener('pointerdown',e=>{if(att||fixed===4||e.target.classList.contains('hz'))return;miss++;bad_();q(['That part is fine, cadet. Look at the real fault.','Not there! Eyes sharp, cadet.','I did not ask about that. Cap, collar, belt, boots!'][miss%3])});
 act={key(e){const m={Digit1:'beret',Digit2:'btn',Digit3:'buckle',Digit4:'shoes'}[e.code];if(m&&!att)fix(m)}};
 function phase2(){att=true;ov.querySelectorAll('.mk').forEach(m=>m.style.display='none');q('Uniform is spotless. Now stand at attention. Hold still until I say stop.');
  $('#pa').innerHTML='<button class="hold" data-testid="attention-hold"><span>HOLD<br>ATTENTION</span></button>';const b=$('.hold');let t0=0,r=0,done=0;
  const stop=()=>{cancelAnimationFrame(r);r=0},tick=()=>{if(done)return;const p=Math.min(1,(performance.now()-t0)/2600);b.style.setProperty('--p',p*100);if(p>=1){done=1;go();return}r=requestAnimationFrame(tick)};
  const on=()=>{if(done||window.__paused)return;t0=performance.now();$('.fig').classList.add('stiff');q('Chest out. Chin up. Do not move!');tick()},off=()=>{if(done)return;stop();b.style.setProperty('--p',0);$('.fig').classList.remove('stiff');if(t0){fid++;t0=0;q('You fidgeted! Stand at attention until I say so.')}};
  const H=hold(b,on,off);act={key(e){if(enter(e)&&!e.repeat)H.dn()},keyup(e){if(enter(e))H.up()}};
  function go(){const s=Math.max(40,100-miss*10-fid*5);setSc('uniform',s);q('Perfect attention. Inspection passed.');sleep(500,()=>outcome(true,'Uniform inspection passed with '+s+' / 100. Now fall in with the company for drill.',null,fin,'CONTINUE'))}}
})}

/* ---------- 3. FALL IN AND DRILL ---------- */
const CMD=[{id:'att',h:'SAVDHAAN!',e:'ATTENTION',k:['ArrowUp','KeyW'],ic:'\u2B06'},{id:'ease',h:'VISHRAAM!',e:'AT EASE',k:['ArrowDown','KeyS'],ic:'\u2B07'},{id:'left',h:'BAAYEN MUD!',e:'LEFT TURN',k:['ArrowLeft','KeyA'],ic:'\u2B05'},{id:'right',h:'DAAYEN MUD!',e:'RIGHT TURN',k:['ArrowRight','KeyD'],ic:'\u27A1'},{id:'back',h:'PEECHE MUD!',e:'ABOUT TURN',k:['Space','Enter','KeyX'],ic:'\u27F2'}];
function drill(fin){intro(2,'FALL IN AND DRILL','Company, listen for my command and obey at once. Savdhaan, Vishraam, Daayen Mud, Baayen Mud, Peeche Mud. Fall in!','FALL IN!',()=>{
 const N=10,NEED=8;
 const run=()=>{clr();step(2,'DRILL');let i=0,okc=0,seq=[],res=[],locked=true;for(let k=0;k<N;k++){let c;do{c=CMD[Math.floor(Math.random()*5)]}while(k&&seq[k-1]===c);seq.push(c)}
  M.innerHTML='<div class="cmd"><b id="dc">FALL IN!</b><span id="de">Get into the line</span></div><div class="drow">'+[0,1,2,3,4].map(k=>'<div class="cd off'+(k===2?' me':'')+'" style="transition-delay:'+k*90+'ms">'+cadet('att',k===2)+'</div>').join('')+'</div><div class="tb"><i id="dt" style="transform:scaleX(0)"></i></div><div class="pips">'+seq.map(()=>'<i></i>').join('')+'</div><div class="pads">'+CMD.map((c,k)=>'<button class="pad" data-i="'+k+'" data-testid="drill-'+c.id+'"><em>'+c.ic+'</em>'+c.e+'</button>').join('')+'</div>';
  const cds=[...ov.querySelectorAll('.cd')],pose=(p,all)=>cds.forEach((c,k)=>{if(all||k===2)sleep(k===2?0:70*Math.abs(k-2),()=>{c.firstElementChild.outerHTML=cadet(p,k===2)})}),pips=ov.querySelectorAll('.pips i');
  sleep(150,()=>cds.forEach(c=>c.classList.remove('off')));sleep(1100,()=>{locked=false;call()});
  function call(){if(i>=N){const win=okc>=NEED,s=okc/N*100;if(win)setSc('drill',s);$('#dc').textContent=win?'COMPANY, DISMISS!':'';$('#de').textContent='';sleep(500,()=>outcome(win,win?'You got '+okc+' of '+N+' commands right. The company moves as one. Now the 1.4 km ground run!':'Only '+okc+' of '+N+' right. You need '+NEED+'. Listen carefully and try again.',run,fin,'CONTINUE'));return}
   const c=seq[i],T=Math.max(1.5,2.5-i*.1);$('#dc').textContent=c.h;$('#de').textContent=c.e;locked=false;const bar=$('#dt');bar.style.transition='none';bar.style.transform='scaleX(1)';void bar.offsetWidth;bar.style.transition='transform '+T+'s linear';bar.style.transform='scaleX(0)';beep(300,.12,'square',.04);
   clearTimeout(call.t);call.t=sleep(T*1000,()=>answer(null))}
  function answer(c){if(locked||paused)return;locked=true;clearTimeout(call.t);const want=seq[i],good=c===want;
   if(good){okc++;pose(want.id,true);ok_();vib(20);pips[i].className='ok';pad(c,'hit')}else{bad_();vib(90);pips[i].className='no';$('#dc').textContent=c?'WRONG!':'TOO SLOW!';if(c)pad(c,'bad');const me=cds[2];me.classList.add('flash')}
   i++;sleep(good?650:900,()=>{cds[2]&&cds[2].classList.remove('flash');call()})}
  const pad=(c,k)=>{const b=ov.querySelector('.pad[data-i="'+CMD.indexOf(c)+'"]');if(b){b.classList.add(k);sleep(260,()=>b.classList.remove(k))}};
  ov.querySelectorAll('.pad').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();answer(CMD[+b.dataset.i])}));
  act={key(e){if(e.repeat)return;const c=CMD.find(x=>x.k.indexOf(e.code)>=0);if(c)answer(c)},onPause(){clearTimeout(call.t)},onResume(){if(!locked&&i<N)call()}}};
 run()})}


